#!/usr/bin/env node
// Capture square post images and a recorded BC/PPO/reference MP4. The short README GIF is generated by readme:gif. Requires trained artifacts.
import { spawnSync } from 'node:child_process'
import { copyFile, mkdir, mkdtemp, rename, rm, writeFile } from 'node:fs/promises'
import { resolve } from 'node:path'
import { chromium, expect } from '../apps/greenhouse-demo/node_modules/@playwright/test/index.mjs'

const root = resolve(import.meta.dirname, '..')
const url = process.env.GREENHOUSE_URL ?? 'http://127.0.0.1:8086'
const screenshots = resolve(root, 'apps/greenhouse-demo/screenshots')
const media = resolve(root, 'apps/greenhouse-demo/media')
await mkdir(resolve(root, '.temp'), { recursive: true })
const temporary = await mkdtemp(resolve(root, '.temp/greenhouse-capture-'))
const frames = resolve(temporary, 'frames')
for (const directory of [screenshots, media, frames]) await mkdir(directory, { recursive: true })
function ffmpeg(args) {
	const result = spawnSync('ffmpeg', ['-hide_banner', '-loglevel', 'error', '-y', ...args], {
		stdio: 'inherit',
	})
	if (result.error) throw result.error
	if (result.status !== 0) throw Error(`ffmpeg exited with ${result.status}`)
}
const browser = await chromium.launch({ channel: 'chrome', headless: true })
try {
	const page = await browser.newPage({
		viewport: { width: 1080, height: 1080 },
		deviceScaleFactor: 1,
		colorScheme: 'dark',
	})
	const errors = []
	page.on('pageerror', (error) => errors.push(error.message))
	const response = await page.request.get(`${url}/api/v1/greenhouse/training`)
	if (!response.ok())
		throw Error(
			`Training API unavailable: HTTP ${response.status()}. Start pnpm dev:greenhouse first.`,
		)
	const catalog = await response.json()
	const bc = catalog.checkpoints.find(
		(item) => item.algorithm === 'bc' && item.round === 3 && item.compatible,
	)
	const preferred = catalog.jobs.find(
		(item) => item.state === 'completed' && item.request.algorithm === 'ppo',
	)?.selected_checkpoint
	const ppo = catalog.checkpoints.find(
		(item) => item.checkpoint_id === preferred && item.compatible,
	)
	if (!bc || !ppo)
		throw Error(
			'Train the documented BC and PPO experiments before capturing the learning comparison.',
		)
	const panel = async (name) => page.getByRole('tab', { name, exact: true }).click()
	const select = async (label, value) => {
		await page.getByLabel(label, { exact: true }).click()
		await page.getByRole('listbox').getByTestId(`choice-${value}`).click()
	}
	const names = []
	const shot = async (name) => {
		await page.waitForTimeout(400)
		await page.screenshot({ path: resolve(temporary, `${name}.png`) })
		names.push(name)
	}
	await page.goto(url)
	await expect(page.getByTestId('renderer-status')).toHaveText('WebGPU active', { timeout: 30000 })
	await expect(page.getByRole('button', { name: 'Start collection', exact: true })).toBeEnabled()
	await page.evaluate(() => document.fonts.ready)
	await shot('overview')
	await panel('Train')
	await select('Saved checkpoint', ppo.checkpoint_id)
	await page.getByRole('button', { name: 'Use selected checkpoint', exact: true }).click()
	await panel('Watch')
	await page.getByRole('button', { name: 'Start collection', exact: true }).click()
	await expect
		.poll(() => page.evaluate(() => window.__greenhouseReview?.pose?.lift ?? 0), { timeout: 20000 })
		.toBeGreaterThan(0.2)
	await page.getByRole('button', { name: 'Pause collection', exact: true }).click()
	await page.getByRole('button', { name: 'Follow', exact: true }).click()
	await shot('learned-carrying')
	await page.getByRole('button', { name: 'Restart seed', exact: true }).click()
	await page.getByRole('button', { name: 'Overview', exact: true }).click()
	await panel('Train')
	await page
		.getByRole('button', { name: 'Use selected checkpoint', exact: true })
		.scrollIntoViewIfNeeded()
	await shot('training')
	await panel('Compare')
	await select('Comparison policy A', bc.checkpoint_id)
	await select('Comparison policy B', ppo.checkpoint_id)
	await page.getByLabel('Comparison seed (10000–10029)').fill('10006')
	const reply = page.waitForResponse(
		(response) =>
			response.url().endsWith('/training/compare') && response.request().method() === 'POST',
	)
	await page.getByRole('button', { name: 'Compare policies', exact: true }).click()
	const comparison = await (await reply).json()
	await expect(page.getByRole('region', { name: 'Comparison playback', exact: true })).toBeVisible()
	await page.getByRole('button', { name: 'Watch 2', exact: true }).click()
	await page.getByLabel('Comparison position', { exact: true }).press('End')
	await page.getByRole('button', { name: 'Watch 3', exact: true }).scrollIntoViewIfNeeded()
	await page.locator('[data-slot="table-container"]').evaluateAll((elements) => {
		for (const element of elements) element.scrollLeft = 0
	})
	await shot('policy-comparison')
	let total = 0
	const timings = []
	for (let entry = 0; entry < 3; entry++) {
		await page.getByRole('button', { name: `Watch ${entry + 1}`, exact: true }).click()
		await page.getByLabel('Comparison position', { exact: true }).press('Home')
		await page.getByRole('button', { name: 'Play comparison rollout', exact: true }).click()
		const first = total
		for (let frame = 0; frame < 50; frame++) {
			await page.screenshot({
				path: resolve(frames, `frame-${String(total++).padStart(4, '0')}.png`),
			})
			const tick = Number(await page.getByTestId('simulation-tick').textContent())
			if (tick >= comparison.entries[entry].rollout.frames.length) break
			await page.waitForTimeout(700)
		}
		await expect(page.getByTestId('simulation-tick')).toHaveText(
			String(comparison.entries[entry].rollout.frames.length),
		)
		timings.push({
			label: comparison.entries[entry].label,
			firstFrame: first,
			frames: total - first,
			outcome: comparison.entries[entry].rollout.failure,
		})
	}
	await page.getByRole('button', { name: 'Return to live', exact: true }).click()
	await panel('Missions')
	await page.getByRole('button', { name: 'Start mission', exact: true }).click()
	await expect(page.getByTestId('mission-status')).toContainText('1/3 delivered', {
		timeout: 25000,
	})
	await page.getByRole('button', { name: 'Pause mission', exact: true }).click()
	await page.getByRole('button', { name: 'Follow', exact: true }).click()
	await shot('mission')
	await page.getByRole('button', { name: 'Cancel mission', exact: true }).click()
	if (errors.length) throw Error(errors.join('\n'))
	const input = resolve(frames, 'frame-%04d.png')
	ffmpeg([
		'-framerate',
		'3',
		'-i',
		input,
		'-vf',
		'fps=30,format=yuv420p',
		'-c:v',
		'libx264',
		'-crf',
		'22',
		'-movflags',
		'+faststart',
		resolve(temporary, 'learning-comparison.mp4'),
	])

	for (const name of names)
		await copyFile(resolve(temporary, `${name}.png`), resolve(screenshots, `${name}.png`))
	for (const name of ['learning-comparison.mp4'])
		await rename(resolve(temporary, name), resolve(media, name))
	const report = {
		viewport: { width: 1080, height: 1080 },
		source:
			'Stored-state validation playback; accelerated capture of BC, PPO and reference on the same validation seed. Live learned carrying and mission screenshots are separate real sessions.',
		seed: 10006,
		bc: bc.checkpoint_id,
		ppo: ppo.checkpoint_id,
		frames: total,
		fps: 3,
		timings,
		screenshots: names,
		errors,
	}
	await writeFile(resolve(media, 'capture.json'), `${JSON.stringify(report, null, 2)}\n`)
	process.stdout.write(`${JSON.stringify(report, null, 2)}\n`)
} finally {
	await browser.close()
	await rm(temporary, { recursive: true, force: true })
}
